Lemma pfin_spec : forall pw r x s A, 0 <= s -> toZ pw = 2 ^ s mod 2 ^ 63 -> toZ r = A mod 2 ^ 63 -> 0 <= A < 2 ^ (s + 1) ->
  pfin pw r = Some x -> toZ x = A /\ A < 2 ^ 62.
Proof.
