Lemma disj_sidesB_in : forall bc kd b k n c m, In (c, m) (disj_sidesB bc kd b k n) ->
  exists c' m', (In (KDisj c' m' c m) kd \/ In (KDisj c m c' m') kd) /\ sub_itvB bc b k n c' m' = true.
Proof.
